import json

class Student:
    def __init__(self, name):
        self.name = name
        self.scores = []

    def average(self):
        if not self.scores:
            return 0
        return sum(self.scores) / len(self.scores)

class GradeBook:
    def __init__(self):
        self.students = {}

    def add_score(self, name, score):
        if name not in self.students:
            self.students[name] = Student(name)
        self.students[name].scores.append(score)

book = GradeBook()
for name, score in [('Ada', 90), ('Bo', 95), ('Ada', 75), ('Bo', 88)]:
    book.add_score(name, score)

data = {name: student.scores for name, student in book.students.items()}

with open('grades.json', 'w') as f:
    json.dump(data, f)

with open('grades.json') as f:
    print(json.load(f))

