        self.name = name
        self.scores = []

    def average(self):
        if not self.scores:
            return 0
        return sum(self.scores) / len(self.scores)

def letter(avg):
    if avg >= 90:
        return 'A'
    elif avg >= 80:
        return 'B'
    elif avg >= 70:
        return 'C'
    return 'F'

